fn busy_at(meetings: List[List[Int]], t: Int) -> Int {
  return meetings.count(fn(o) => o.get_or(0, 0) <= t and o.get_or(1, 0) > t)
}

pub fn rooms(meetings: List[List[Int]]) -> Int {
  let counts = meetings.map(fn(m) => busy_at(meetings, m.get_or(0, 0)))
  return counts.max().unwrap_or(0)
}
